import statistics

def parse(nwk):
    s=nwk.strip()
    if s.endswith(';'): s=s[:-1]
    pos=0
    def node():
        nonlocal pos
        if s[pos]=='(':
            pos+=1
            ch=[]
            while True:
                ch.append(node())
                if pos<len(s) and s[pos]==',':
                    pos+=1; continue
                if pos<len(s) and s[pos]==')':
                    pos+=1; break
                raise ValueError((s,pos))
            st=pos
            while pos<len(s) and s[pos] not in ',);': pos+=1
            lab=s[st:pos]
            length=float(lab.split(':')[1]) if ':' in lab else 0.0
            return ('int',ch,length)
        st=pos
        while pos<len(s) and s[pos] not in ',();': pos+=1
        tok=s[st:pos]
        if ':' in tok:
            name, length=tok.split(':')
            return ('leaf',name,float(length))
        return ('leaf',tok,0.0)
    return node()

def all_pair_dists(nwk):
    t=parse(nwk)
    edges=[]; idx=0
    def walk(n, parent=None, plen=0.0):
        nonlocal idx
        myid=idx; idx+=1
        if parent is not None:
            edges.append((parent,myid,plen))
        if n[0]=='int':
            for c in n[1]: walk(c,myid,c[2])
        return myid
    walk(t)
    leaves=[]; 
    def leaveswalk(n):
        if n[0]=='leaf': leaves.append(n[1])
        else:
            for c in n[1]: leaveswalk(c)
    leaveswalk(t)
    # map names to ids via second walk
    name_id={}
    def mapwalk(n):
        nonlocal idx
        myid=idx; idx+=1
        if n[0]=='leaf': name_id[n[1]]=myid
        else:
            for c in n[1]: mapwalk(c)
    idx=0; mapwalk(t)
    adj={}
    for u,v,w in edges:
        adj.setdefault(u,{})[v]=w
        adj.setdefault(v,{})[u]=w
    from collections import deque
    def dist(a,b):
        seen={a}; q=deque([(a,0.0)])
        while q:
            u,d=q.popleft()
            if u==b:return d
            for v,w in adj[u].items():
                if v not in seen:
                    seen.add(v); q.append((v,d+w))
    ds=[]
    for i,a in enumerate(leaves):
        for b in leaves[i+1:]:
            ds.append(dist(name_id[a],name_id[b]))
    return sorted(ds), statistics.median(ds)

for f in ['981902at2759.faa.mafft.clipkit.treefile','981902at2759.faa.mafft.clipkit.bionj']:
    import zipfile
    n=zipfile.ZipFile('inputs/scogs_fungi.zip').read(f).decode().strip()
    ds,med=all_pair_dists(n)
    print(f, ds, med)
